 public static void TotalData(){
     String DataAccessed = Dequeue();
     Boolean Flag = false;
     if(NumberRecords == 0){
         Records[NumberRecords] = new RecordData(DataAccessed, 1);
         NumberRecords ++;
         Flag = true;
     }else{
         for(Integer X = 0; X < NumberRecords; X++){
             if(Records[X].ID.equals(DataAccessed)){
                 Records[X].Total++;
                 Flag = true;
             }
         }
     }
